3. IPC Handler

New Channel: TASK_HEALTH_CHECK (in apps/frontend/src/shared/constants/ipc.ts)

Handler Location: apps/frontend/src/main/ipc-handlers/task/health-check-handlers.ts (new file)

Handler Logic:

```
ipcMain.handle(TASK_HEALTH_CHECK, async (event, projectId: string) => {
  const results: TaskHealthCheckResult[] = [];
  for (const task of projectStore.getTasks(projectId)) {
    const issues: HealthIssue[] = [];
    // Check 1: Stuck task
    if (task.status === 'in_progress' && !agentManager.isRunning(task.id)) {
      issues.push({
        type: 'stuck',
        severity: 'error',
        message: 'Task is marked as in_progress but no agent process is running',
        details: 'The task may have crashed or the process was killed externally'
      });
    }
    // Check 2: Failed status
    if (task.status === 'error' || task.executionProgress?.phase === 'failed') {
      issues.push({
        type: 'failed',
        severity: 'error',
        message: 'Task execution failed',
        details: task.errorInfo?.message
      });
    }
    // Check 3: Failed subtasks
    const failedSubtasks = task.subtasks.filter(s => s.status === 'failed');
    if (failedSubtasks.length > 0) {
      issues.push({
        type: 'failed',
        severity: 'error',
        message: `${failedSubtasks.length} subtask(s) failed`,
        details: failedSubtasks.map(s => s.title).join(', ')
      });
    }
    // Check 4: QA rejected
    if (task.qaReport?.signoff?.status === 'rejected') {
      issues.push({
        type: 'qa_rejected',
        severity: 'warning',
        message: 'QA review rejected changes',
        details: 'See QA_FIX_REQUEST.md for required fixes'
      });
    }
    // Check 5: Missing or corrupted artifacts (on-disk check)
    const specPath = path.join(task.specsPath || '', 'spec.md');
    const planPath = path.join(task.specsPath || '', 'implementation_plan.json');
    if (!fs.existsSync(specPath)) {
      issues.push({
        type: 'missing_artifact',
        severity: 'error',
        message: 'Missing spec.md file',
        details: `Expected at: ${specPath}`
      });
    }
    if (fs.existsSync(planPath)) {
      try {
        JSON.parse(fs.readFileSync(planPath, 'utf-8'));
      } catch {
        issues.push({
          type: 'corrupted',
          severity: 'error',
          message: 'Corrupted implementation_plan.json',
          details: 'Invalid JSON, file may need manual repair'
        });
      }
    }
    results.push({
      taskId: task.id,
      title: task.title,
      status: task.status,
      isHealthy: issues.length === 0,
      issues,
      recoveryActions: buildRecoveryActions(task, issues)
    });
  }
  return results.filter(r => !r.isHealthy || r.issues.length > 0);
});
```

