## Implementation Details

### Step 1: Create the Auth Module

```typescript
// apps/frontend/src/main/auth/claude-auth-resolver.ts

import { getClaudeProfileManager } from '../claude-profile-manager';
import { existsSync, readFileSync } from 'fs';
import path from 'path';
import { app } from 'electron';

// ... types as defined above ...

export function resolveClaudeAuth(options?: ResolveAuthOptions): ClaudeAuthConfig {
  const profileManager = getClaudeProfileManager();
  const profile = options?.profileId
    ? profileManager.getProfile(options.profileId)
    : profileManager.getActiveProfile();

  // Priority 1: OAuth from profile
  if (profile?.oauthToken) {
    const token = options?.profileId
      ? profileManager.getProfileToken(options.profileId)
      : profileManager.getActiveProfileToken();

    if (token) {
      return {
        method: 'oauth',
        source: 'claude_profile',
        tokenPrefix: maskToken(token),
        envVars: { CLAUDE_CODE_OAUTH_TOKEN: token }
      };
    }
  }

  // Load .env file
  const envVars = loadEnvFile(options?.envFilePath);

  // Priority 2: OAuth from .env
  if (envVars.CLAUDE_CODE_OAUTH_TOKEN) {
    return {
      method: 'oauth',
      source: 'env_file',
      tokenPrefix: maskToken(envVars.CLAUDE_CODE_OAUTH_TOKEN),
      envVars: { CLAUDE_CODE_OAUTH_TOKEN: envVars.CLAUDE_CODE_OAUTH_TOKEN }
    };
  }

  // Priority 3: API key from .env (with warning)
  if (envVars.ANTHROPIC_API_KEY && options?.allowApiKeyFallback !== false) {
    return {
      method: 'api_key',
      source: 'env_file',
      tokenPrefix: maskToken(envVars.ANTHROPIC_API_KEY),
      envVars: { ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY },
      billingWarning: 'Using ANTHROPIC_API_KEY - this may incur API billing charges'
    };
  }

  // No auth available
  return {
    method: 'none',
    source: 'none',
    tokenPrefix: '',
    envVars: {}
  };
}

export function getClaudeSubprocessEnv(
  baseEnv: NodeJS.ProcessEnv = process.env,
  options?: ResolveAuthOptions
): Record<string, string> {
  // Remove shell auth vars to prevent accidental usage
  const { 
    ANTHROPIC_API_KEY: _shellApiKey, 
    CLAUDE_CODE_OAUTH_TOKEN: _shellOauth,
    ...cleanEnv 
  } = baseEnv;

  // Get resolved auth
  const authConfig = resolveClaudeAuth(options);

  // Get profile config dir if applicable
  const profileManager = getClaudeProfileManager();
  const profile = options?.profileId
    ? profileManager.getProfile(options.profileId)
    : profileManager.getActiveProfile();

  const profileEnv: Record<string, string> = {};
  if (profile && !profile.isDefault && profile.configDir) {
    profileEnv.CLAUDE_CONFIG_DIR = profile.configDir;
  }

  return {
    ...cleanEnv as Record<string, string>,
    ...authConfig.envVars,
    ...profileEnv
  };
}
```

