```typescript
import { writeFileSync, renameSync, unlinkSync, readFileSync } from 'fs';
import { dirname, join } from 'path';
import { randomBytes } from 'crypto';

/**
 * Write file atomically using temp file + rename pattern.
 * Safe on all platforms when source and destination are on same volume.
 */
export function writeFileAtomic(filePath: string, data: string): void {
  const dir = dirname(filePath);
  const tempPath = join(dir, `.tmp.${randomBytes(8).toString('hex')}`);

  try {
    writeFileSync(tempPath, data, 'utf-8');
    renameSync(tempPath, filePath);  // Atomic on same volume
  } catch (error) {
    // Clean up temp file on failure
    try { unlinkSync(tempPath); } catch {}
    throw error;
  }
}

/**
 * Write file with retry logic for Windows file locking.
 * Retries with exponential backoff on EACCES, EBUSY, EPERM.
 */
export async function writeFileWithRetry(
  filePath: string,
  data: string,
  maxRetries = 5,
  initialDelayMs = 100
): Promise<void> {
  let lastError: Error | undefined;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      writeFileAtomic(filePath, data);
      return;
    } catch (error: any) {
      const code = error?.code;
      // Retry on file locking errors
      if (code === 'EACCES' || code === 'EBUSY' || code === 'EPERM' || code === 'ENOENT') {
        lastError = error;
        const delay = initialDelayMs * Math.pow(2, attempt);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;  // Non-retryable error
    }
  }

  throw lastError ?? new Error(`Failed to write ${filePath} after ${maxRetries} attempts`);
}

/**
 * Read file with retry logic for Windows file locking.
 */
export async function readFileWithRetry(
  filePath: string,
  maxRetries = 5,
  initialDelayMs = 100
): Promise<string> {
  let lastError: Error | undefined;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return readFileSync(filePath, 'utf-8');
    } catch (error: any) {
      const code = error?.code;
      if (code === 'EACCES' || code === 'EBUSY' || code === 'EPERM') {
        lastError = error;
        const delay = initialDelayMs * Math.pow(2, attempt);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }

  throw lastError ?? new Error(`Failed to read ${filePath} after ${maxRetries} attempts`);
}
```

