// apps/frontend/src/main/utils/file-lock.ts
import { openSync, closeSync, unlinkSync } from 'fs';
import { join, dirname } from 'path';

export class FileLock {
  private lockPath: string;
  private fd: number | null = null;

  constructor(filePath: string) {
    this.lockPath = join(dirname(filePath), `.${basename(filePath)}.lock`);
  }

  async acquire(timeoutMs = 5000): Promise<void> {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      try {
        this.fd = openSync(this.lockPath, 'wx');  // Exclusive create
        return;
      } catch (error: any) {
        if (error.code === 'EEXIST') {
          await new Promise(r => setTimeout(r, 50));
          continue;
        }
        throw error;
      }
    }
    throw new Error(`Timeout acquiring lock: ${this.lockPath}`);
  }

  release(): void {
    if (this.fd !== null) {
      closeSync(this.fd);
      try { unlinkSync(this.lockPath); } catch {}
      this.fd = null;
    }
  }
}
